-- Description:	Loading Is Auto Stock Item Generat
-- [dbo].[SP_GetIsAutoGenerated]1
-- =============================================
create PROCEDURE [dbo].[SP_GetIsAutoGenerated]
	@PropertyID int
AS
BEGIN
	SET NOCOUNT ON;

    SELECT AutoStockItemCode
	FROM Companies
	WHERE CompanyID = @PropertyID
END

GO

